/**
 * `pnpm ci:golden-path`: checks that packages/shared/src/testing/fixtures/golden-path.jsonl
 * (just regenerated by `pnpm fixtures:golden-path`) is a valid, complete golden path.
 *
 * The file is allowed to differ from the committed one (ids and short codes are random);
 * it is not allowed to be malformed or to tell a different story.
 */
import { appendFileSync, readFileSync } from "node:fs";
import { ENTITY_REFS, EVENT_ACTORS, type PlatypusEvent } from "../../packages/shared/src/events/types";
import { GOLDEN_PATH_FIXTURE } from "../../packages/shared/src/testing/replay";

const VOICE_TOOLS_IN_ORDER = ["check_slot", "hold_slot", "create_booking", "record_consent", "set_text_number"];
const REQUIRED_TYPES = ["business.listed", "agent.tool_called", "darwin.searched", "booking.pending", "hold.placed", "call.placed", "call.ended", "call.transcribed", "voice.tool_called", "consent.recorded", "business.channel_changed", "message.sent", "message.received", "reply.classified", "booking.confirmed"];

const errors: string[] = [];
const lines = readFileSync(GOLDEN_PATH_FIXTURE, "utf8").split("\n").filter((l) => l.trim());
const events: PlatypusEvent[] = [];

lines.forEach((line, i) => {
  const where = `line ${i + 1}`;
  let e: PlatypusEvent;
  try {
    e = JSON.parse(line) as PlatypusEvent;
  } catch {
    errors.push(`${where}: not JSON`);
    return;
  }
  if (typeof e.id !== "string" || !e.id.startsWith("evt_")) errors.push(`${where}: id must start with evt_`);
  if (typeof e.type !== "string" || !/^[a-z_]+\.[a-z_]+$/.test(e.type)) errors.push(`${where}: type "${e.type}" is not noun.verb`);
  if (!(EVENT_ACTORS as readonly string[]).includes(e.actor)) errors.push(`${where}: unknown actor "${e.actor}"`);
  if (!e.refs || typeof e.refs !== "object") errors.push(`${where}: refs missing`);
  else for (const key of Object.keys(e.refs)) if (!(ENTITY_REFS as readonly string[]).includes(key)) errors.push(`${where}: unknown ref "${key}"`);
  if (!e.payload || typeof e.payload !== "object") errors.push(`${where}: payload missing`);
  if (e.reason !== null && typeof e.reason !== "string") errors.push(`${where}: reason must be a string or null`);
  if (typeof e.confidence !== "number" || e.confidence < 0 || e.confidence > 1) errors.push(`${where}: confidence must be within 0..1`);
  if (Number.isNaN(Date.parse(e.created_at))) errors.push(`${where}: created_at is not a timestamp`);
  events.push(e);
});

for (let i = 1; i < events.length; i++) {
  if (events[i]!.id <= events[i - 1]!.id) errors.push(`event ids are not strictly increasing at line ${i + 1}`);
}

const types = new Set(events.map((e) => e.type));
for (const t of REQUIRED_TYPES) if (!types.has(t)) errors.push(`missing event type ${t}`);

const tools = events.filter((e) => e.type === "voice.tool_called").map((e) => e.payload.tool);
if (JSON.stringify(tools) !== JSON.stringify(VOICE_TOOLS_IN_ORDER)) errors.push(`voice tools ran as ${JSON.stringify(tools)}, expected ${JSON.stringify(VOICE_TOOLS_IN_ORDER)}`);

// Non-negotiable 1: a booking is confirmed only with the owner's evidence, never from a transcript alone.
const confirmed = events.filter((e) => e.type === "booking.confirmed");
if (confirmed.length !== 2) errors.push(`expected 2 confirmed bookings (one by call, one by text), got ${confirmed.length}`);
const kinds = confirmed.map((e) => (e.payload.evidence as { kind?: string } | undefined)?.kind);
if (JSON.stringify(kinds) !== JSON.stringify(["call", "text"])) errors.push(`confirmation evidence was ${JSON.stringify(kinds)}, expected ["call","text"]`);

// Non-negotiable 3: the text goes out only after consent was recorded.
const consentAt = events.findIndex((e) => e.type === "consent.recorded");
const firstText = events.findIndex((e) => e.type === "message.sent");
if (consentAt < 0 || firstText < consentAt) errors.push("a message was sent before consent was recorded");

const summary = [
  "### Golden path fixture",
  "",
  `${events.length} events, ${types.size} event types, voice tools ${tools.join(" → ")}, confirmations by ${kinds.join(" then ")}.`,
  "",
  errors.length ? errors.map((e) => `- ${e}`).join("\n") : "Valid.",
].join("\n");
console.log(summary);
if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n\n`);
if (errors.length) process.exitCode = 1;
